        x = mb.add(x=x, y=1.2, name="add")
        x = mb.transpose(x=x, perm=[0, 2, 3, 1])
        x = mb.square(x=x, name="output_0")
        x = mb.tanh(x=x, name="output_1")
        x = mb.transpose(x=x, perm=[0, 2, 3, 1])
        return x
    return prog

