def psnr(pred, target):
    mse = torch.mean((pred - target) ** 2)
    eps = 1e-5
    eps2 = 1e-10
    return 20 * torch.log10((torch.max(torch.abs(target)) + eps) / (torch.sqrt(mse) + eps2))
